	if opts.Update {
		cmdUpdate(cfg, opts)
		return
	}

	if opts.Directories {
		cmdDirectories(cfg, opts)
		return
	}

	if opts.Tags {
		cmdTags(cfg, opts)
		return
	}

	if opts.Brief || opts.List {
		cmdList(cfg, opts)
		return
	}

	if opts.Search != "" || (opts.Regex && len(opts.Args) == 0) {
		cmdSearch(cfg, opts)
		return
	}

	if opts.Edit != "" {
		cmdEdit(cfg, opts)
		return
	}

	if opts.Rm != "" {
		cmdRm(cfg, opts)
		return
	}

	// Default: view a cheatsheet
	if len(opts.Args) == 0 {
		// no args and no other command -> show help
		printHelp(os.Stdout)
		os.Exit(0)
	}

	cmdView(cfg, opts)
}
