cat > /workspace/src/args.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

type Options struct {
	All          bool
	Brief        bool
	Colorize     bool
	Completion   string
	Conf         bool
	Directories  bool
	Edit         string
	Help         bool
	Init         bool
	List         bool
	Path         string
	Regex        bool
	Rm           string
	Search       string
	Tag          string
	Tags         bool
	Update       bool
	Version      bool
	Args         []string
}

type flagSpec struct {
	long      string
	short     string
	hasValue  bool
	valueName string
	desc      string
}

var flagSpecs = []flagSpec{
	{"all", "a", false, "", "Search among all cheatpaths"},
	{"brief", "b", false, "", "List cheatsheets without file paths"},
	{"colorize", "c", false, "", "Colorize output"},
	{"completion", "", true, "shell", "Generate shell completion script (shell: bash, zsh, fish, powershell)"},
	{"conf", "", false, "", "Display the config file path"},
	{"directories", "d", false, "", "List cheatsheet directories"},
	{"edit", "e", true, "cheatsheet", "Edit cheatsheet"},
	{"help", "h", false, "", "help for cheat"},
	{"init", "", false, "", "Write a default config file to stdout"},
	{"list", "l", false, "", "List cheatsheets"},
	{"path", "p", true, "name", "Return only sheets found on cheatpath name"},
	{"regex", "r", false, "", "Treat search <phrase> as a regex"},
	{"rm", "", true, "cheatsheet", "Remove (delete) cheatsheet"},
	{"search", "s", true, "phrase", "Search cheatsheets for phrase"},
	{"tag", "t", true, "tag", "Return only sheets matching tag"},
	{"tags", "T", false, "", "List all tags in use"},
	{"update", "u", false, "", "Update git-backed cheatpaths"},
	{"version", "v", false, "", "Print the version number"},
}

func findLongFlag(name string) *flagSpec {
	for i := range flagSpecs {
		if flagSpecs[i].long == name {
			return &flagSpecs[i]
		}
	}
	return nil
}

func findShortFlag(letter string) *flagSpec {
	for i := range flagSpecs {
		if flagSpecs[i].short == letter {
			return &flagSpecs[i]
		}
	}
	return nil
}

func parseArgs(args []string) (*Options, error) {
	opts := &Options{}
	i := 0

	setValue := func(spec *flagSpec, value string) {
		switch spec.long {
		case "all":
			opts.All = true
		case "brief":
			opts.Brief = true
		case "colorize":
			opts.Colorize = true
		case "completion":
			opts.Completion = value
		case "conf":
			opts.Conf = true
		case "directories":
			opts.Directories = true
		case "edit":
			opts.Edit = value
		case "help":
			opts.Help = true
		case "init":
			opts.Init = true
		case "list":
			opts.List = true
		case "path":
			opts.Path = value
		case "regex":
			opts.Regex = true
		case "rm":
			opts.Rm = value
		case "search":
			opts.Search = value
		case "tag":
			opts.Tag = value
		case "tags":
			opts.Tags = true
		case "update":
			opts.Update = true
		case "version":
			opts.Version = true
		}
	}

	for i < len(args) {
		arg := args[i]

		if arg == "--" {
			opts.Args = append(opts.Args, args[i+1:]...)
			break
		}

		if strings.HasPrefix(arg, "--") {
			// Long flag
			rest := arg[2:]
			var name, value string
			hasValue := false
			if eq := strings.Index(rest, "="); eq >= 0 {
				name = rest[:eq]
				value = rest[eq+1:]
				hasValue = true
			} else {
				name = rest
			}

			spec := findLongFlag(name)
			if spec == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}

			if spec.hasValue {
				if !hasValue {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					value = args[i]
				}
				setValue(spec, value)
			} else {
				if hasValue {
					// boolean flags can also be passed with = (true/false)
					// but for simplicity, treat as error
					return nil, fmt.Errorf("flag --%s does not take a value", name)
				}
				setValue(spec, "")
			}
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") && len(arg) > 1 && arg != "-" {
			// Short flag(s), could be grouped like -abc or -s value or -svalue
			rest := arg[1:]
			for len(rest) > 0 {
				letter := string(rest[0])
				rest = rest[1:]
				spec := findShortFlag(letter)
				if spec == nil {
					return nil, fmt.Errorf("unknown shorthand flag: '%s' in -%s", letter, arg[1:])
				}
				if spec.hasValue {
					var value string
					if len(rest) > 0 {
						if rest[0] == '=' {
							value = rest[1:]
						} else {
							value = rest
						}
						rest = ""
						setValue(spec, value)
					} else {
						if i+1 >= len(args) {
							return nil, fmt.Errorf("flag needs an argument: '%s' in -%s", letter, letter)
						}
						i++
						value = args[i]
						setValue(spec, value)
					}
				} else {
					setValue(spec, "")
				}
			}
			i++
			continue
		}

		// Positional
		opts.Args = append(opts.Args, arg)
		i++
	}

	return opts, nil
}

var helpText = `cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

Flags:
  -a, --all                Search among all cheatpaths
  -b, --brief              List cheatsheets without file paths
  -c, --colorize           Colorize output
      --completion shell   Generate shell completion script (shell: bash, zsh, fish, powershell)
      --conf               Display the config file path
  -d, --directories        List cheatsheet directories
  -e, --edit cheatsheet    Edit cheatsheet
  -h, --help               help for cheat
      --init               Write a default config file to stdout
  -l, --list               List cheatsheets
  -p, --path name          Return only sheets found on cheatpath name
  -r, --regex              Treat search <phrase> as a regex
      --rm cheatsheet      Remove (delete) cheatsheet
  -s, --search phrase      Search cheatsheets for phrase
  -t, --tag tag            Return only sheets matching tag
  -T, --tags               List all tags in use
  -u, --update             Update git-backed cheatpaths
  -v, --version            Print the version number
`

func printHelp(w interface{}) {
	// Use fmt for writing
	type stringWriter interface {
		Write(p []byte) (n int, err error)
	}
	if sw, ok := w.(stringWriter); ok {
		sw.Write([]byte(helpText))
	}
}
