package main

import (
	"fmt"
	"strings"
)

// A minimal YAML parser for our specific use cases:
//   - cheat config file (scalar values at top-level, plus `cheatpaths:` list of mappings)
//   - cheatsheet frontmatter (scalars like syntax, plus `tags:` list)
//
// It's not a general YAML parser. It supports enough syntax to parse the
// formats that cheat emits and typically encounters.

type YamlNode struct {
	// one of: scalar, mapping, sequence, null
	Kind string
	Str  string
	Map  []YamlPair // ordered map
	Seq  []*YamlNode
}

type YamlPair struct {
	Key string
	Val *YamlNode
}

type yamlLine struct {
	indent int
	text   string // without leading whitespace and without trailing \r\n
	orig   string // original line text
	num    int    // 1-indexed
}

func stripComment(line string) string {
	// Strip trailing # comments but only when '#' is preceded by whitespace or is the first non-space char
	// We need to be careful with quoted strings. For our purposes, keep it simple: don't strip comments inside "..." or '...'
	inSingle := false
	inDouble := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		switch c {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble {
				if i == 0 || line[i-1] == ' ' || line[i-1] == '\t' {
					return strings.TrimRight(line[:i], " \t")
				}
			}
		}
	}
	return line
}

func readYamlLines(src string) []yamlLine {
	var out []yamlLine
	for i, raw := range strings.Split(src, "\n") {
		// Strip CR
		raw = strings.TrimRight(raw, "\r")
		// Skip completely blank or comment-only lines
		trimmed := strings.TrimLeft(raw, " \t")
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		// Strip trailing inline comment
		raw = stripComment(raw)
		trimmed = strings.TrimLeft(raw, " \t")
		if trimmed == "" {
			continue
		}
		indent := len(raw) - len(trimmed)
		out = append(out, yamlLine{indent: indent, text: trimmed, orig: raw, num: i + 1})
	}
	return out
}

func yamlParse(src string) (*YamlNode, error) {
	lines := readYamlLines(src)
	if len(lines) == 0 {
		return &YamlNode{Kind: "null"}, nil
	}
	idx := 0
	node, err := yamlParseNode(lines, &idx, 0)
	if err != nil {
		return nil, err
	}
	return node, nil
}

// yamlParseNode parses a block starting at lines[*idx] with at least minIndent.
// It returns when a line with less indent is encountered.
func yamlParseNode(lines []yamlLine, idx *int, minIndent int) (*YamlNode, error) {
	if *idx >= len(lines) {
		return &YamlNode{Kind: "null"}, nil
