func splitMapKey(line string) (string, string, error) {
	// Find ':' outside quoted string, either at end or followed by space
	inSingle := false
	inDouble := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		switch c {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case ':':
			if !inSingle && !inDouble {
				if i == len(line)-1 || line[i+1] == ' ' || line[i+1] == '\t' {
					key := strings.TrimSpace(line[:i])
					key = unquoteStr(key)
					rest := ""
					if i+1 < len(line) {
						rest = line[i+1:]
					}
					return key, rest, nil
				}
