		if !strings.HasSuffix(text, "]") {
			return nil, fmt.Errorf("yaml: line %d: did not find expected node content", lineNum)
		}
		inner := text[1 : len(text)-1]
		node := &YamlNode{Kind: "sequence"}
		if strings.TrimSpace(inner) == "" {
			return node, nil
		}
		items, err := splitFlow(inner)
		if err != nil {
			return nil, fmt.Errorf("yaml: line %d: %s", lineNum, err.Error())
		}
		for _, item := range items {
			n, err := parseScalar(item, lineNum)
			if err != nil {
				return nil, err
			}
			node.Seq = append(node.Seq, n)
		}
		return node, nil
	}
	if strings.HasPrefix(text, "{") {
		if !strings.HasSuffix(text, "}") {
			return nil, fmt.Errorf("yaml: line %d: did not find expected node content", lineNum)
		}
		inner := text[1 : len(text)-1]
		node := &YamlNode{Kind: "mapping"}
		if strings.TrimSpace(inner) == "" {
			return node, nil
		}
		items, err := splitFlow(inner)
		if err != nil {
			return nil, fmt.Errorf("yaml: line %d: %s", lineNum, err.Error())
		}
		for _, item := range items {
			k, v, err := splitMapKey(item)
			if err != nil {
				return nil, fmt.Errorf("yaml: line %d: %s", lineNum, err.Error())
			}
			vn, err := parseScalar(strings.TrimSpace(v), lineNum)
			if err != nil {
				return nil, err
			}
			node.Map = append(node.Map, YamlPair{Key: k, Val: vn})
		}
		return node, nil
	}
	// Scalar value (quoted or plain)
	return &YamlNode{Kind: "scalar", Str: unquoteStr(text)}, nil
}

func splitFlow(inner string) ([]string, error) {
	var parts []string
	depth := 0
	inSingle := false
	inDouble := false
	start := 0
	for i := 0; i < len(inner); i++ {
		c := inner[i]
		switch c {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '[', '{':
			if !inSingle && !inDouble {
				depth++
			}
		case ']', '}':
			if !inSingle && !inDouble {
				depth--
			}
		case ',':
			if depth == 0 && !inSingle && !inDouble {
				parts = append(parts, strings.TrimSpace(inner[start:i]))
				start = i + 1
			}
		}
	}
	if inSingle || inDouble || depth != 0 {
		return nil, fmt.Errorf("did not find expected node content")
	}
	last := strings.TrimSpace(inner[start:])
	if last != "" {
		parts = append(parts, last)
	}
	return parts, nil
}

// Helpers to access parsed nodes.

func (n *YamlNode) GetString(key string) (string, bool) {
	if n == nil || n.Kind != "mapping" {
		return "", false
	}
	for _, p := range n.Map {
		if p.Key == key {
			if p.Val == nil {
				return "", true
			}
			if p.Val.Kind == "scalar" {
				return p.Val.Str, true
			}
			if p.Val.Kind == "null" {
				return "", true
			}
		}
	}
	return "", false
}

func (n *YamlNode) GetBool(key string) (bool, bool) {
	s, ok := n.GetString(key)
	if !ok {
		return false, false
	}
	switch strings.ToLower(s) {
	case "true", "yes", "on":
		return true, true
	case "false", "no", "off", "":
		return false, true
	}
	return false, false
}

func (n *YamlNode) GetNode(key string) *YamlNode {
	if n == nil || n.Kind != "mapping" {
		return nil
	}
	for _, p := range n.Map {
		if p.Key == key {
			return p.Val
		}
	}
	return nil
}

func (n *YamlNode) AsStrings() []string {
	if n == nil {
		return nil
	}
	if n.Kind == "sequence" {
		out := make([]string, 0, len(n.Seq))
		for _, it := range n.Seq {
			if it.Kind == "scalar" {
				out = append(out, it.Str)
			}
		}
		return out
	}
	if n.Kind == "scalar" {
		return []string{n.Str}
	}
	return nil
}
