	}
	return false, false
}

func (n *YamlNode) GetNode(key string) *YamlNode {
	if n == nil || n.Kind != "mapping" {
		return nil
	}
	for _, p := range n.Map {
		if p.Key == key {
			return p.Val
		}
	}
	return nil
}

