func expandGlob(pattern string) ([]string, error) {
	// Basic handling - for our purposes, just stat the path
	if strings.Contains(pattern, "*") {
		// Try glob. Go's path/filepath.Glob doesn't support **; we won't support it
		matches, err := filepath.Glob(pattern)
		if err != nil {
			return nil, err
		}
		return matches, nil
	}
	if _, err := os.Stat(pattern); err != nil {
		return nil, nil
	}
	return []string{pattern}, nil
}

func findCwdCheatpath() *Cheatpath {
	cwd, err := os.Getwd()
	if err != nil {
		return nil
	}
	cur := cwd
	for {
		candidate := filepath.Join(cur, ".cheat")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return &Cheatpath{
				Name:     "cwd",
				Path:     candidate,
				Tags:     nil,
				Readonly: false,
			}
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return nil
}
