	"sort"
	"strings"
)

type Sheet struct {
	Title    string   // e.g., "tar" or "foo/bar"
	Path     string   // full filesystem path
	Cheatpath string  // name of the cheatpath
	CheatpathPath string // filesystem path of the cheatpath
	Readonly bool
	Syntax   string
	Tags     []string // union of cheatpath tags and frontmatter tags
	Text     string   // body after frontmatter
}

func loadSheet(title, path, cheatpath, cheatpathPath string, cpTags []string, readonly bool) (*Sheet, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read: %s", err.Error())
	}
	fm, body, err := parseFrontMatter(string(data))
	if err != nil {
		return nil, fmt.Errorf("failed to parse front-matter: %s", err.Error())
	}

	s := &Sheet{
		Title:         title,
		Path:          path,
		Cheatpath:     cheatpath,
		CheatpathPath: cheatpathPath,
		Readonly:      readonly,
		Text:          body,
	}
	if fm != nil {
		if v, ok := fm.GetString("syntax"); ok {
			s.Syntax = v
		}
		if tn := fm.GetNode("tags"); tn != nil {
			s.Tags = tn.AsStrings()
		}
	}
	// Union of cheatpath tags + frontmatter tags (deduped, sorted in output)
	tagSet := map[string]bool{}
	for _, t := range cpTags {
		tagSet[t] = true
	}
	for _, t := range s.Tags {
		tagSet[t] = true
	}
	s.Tags = make([]string, 0, len(tagSet))
	for t := range tagSet {
		s.Tags = append(s.Tags, t)
	}
	sort.Strings(s.Tags)
	return s, nil
}

func parseFrontMatter(content string) (*YamlNode, string, error) {
	if !strings.HasPrefix(content, "---") {
		return nil, content, nil
	}
	// Must have content after the first ---
	rest := content[3:]
	// After the opening ---, there should be a newline immediately (or whitespace+newline)
	if len(rest) == 0 || (rest[0] != '\n' && rest[0] != '\r') {
		// not a frontmatter delimiter
		return nil, content, nil
	}
	// find closing ---
	// iterate line-by-line
	lines := strings.SplitAfter(rest, "\n")
	var fmLines []string
	found := -1
	// skip first content right after "---" - rest starts with \n (or \r\n)
	startLine := 0
	// lines[0] after SplitAfter includes content through first \n; in our case rest[0]=='\n' so lines[0]="\n"
	for i := 0; i < len(lines); i++ {
		ln := lines[i]
		clean := strings.TrimRight(ln, "\r\n")
		if i == 0 {
			// first newline; advance
			if strings.TrimSpace(clean) != "" {
				// Not a valid frontmatter if content immediately after ---
				return nil, content, nil
			}
			startLine = 1
			continue
		}
		if clean == "---" || clean == "..." {
			found = i
			break
		}
		fmLines = append(fmLines, ln)
	}
	if found < 0 {
		return nil, "", fmt.Errorf("failed to delimit frontmatter")
	}
	// body starts after the line `---`
	bodyParts := lines[found+1:]
	body := strings.Join(bodyParts, "")

	fmText := strings.Join(fmLines, "")
	// Trim trailing newline
	fmNode, err := yamlParse(fmText)
	if err != nil {
		return nil, "", fmt.Errorf("failed to unmarshal frontmatter: %s", err.Error())
	}
	_ = startLine
	return fmNode, body, nil
}

// LoadSheets walks all cheatpaths and loads all sheets. Cheatsheets with the
// same title in later (more local) cheatpaths override earlier ones in the map.
// We return all sheets (duplicates included) in a list; callers can filter.
func LoadSheets(cfg *Config) ([]*Sheet, error) {
	var sheets []*Sheet
	for _, cp := range cfg.Cheatpaths {
		err := filepath.Walk(cp.Path, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if info.IsDir() {
				// skip hidden directories (like .git)
				base := filepath.Base(path)
				if strings.HasPrefix(base, ".") && path != cp.Path {
					return filepath.SkipDir
				}
				return nil
			}
			base := filepath.Base(path)
			if strings.HasPrefix(base, ".") {
				return nil
			}
			rel, err := filepath.Rel(cp.Path, path)
			if err != nil {
				return err
			}
			title := filepath.ToSlash(rel)
			s, err := loadSheet(title, path, cp.Name, cp.Path, cp.Tags, cp.Readonly)
			if err != nil {
				return fmt.Errorf("failed to load sheet: %s, path: %s, err: %s", title, path, err.Error())
			}
			sheets = append(sheets, s)
			return nil
		})
		if err != nil {
			return nil, fmt.Errorf("failed to load cheatsheets: %s", err.Error())
		}
	}
	return sheets, nil
}

// filteredSheets applies the path/tag filters from options.
func filteredSheets(sheets []*Sheet, opts *Options) []*Sheet {
	var out []*Sheet
	for _, s := range sheets {
		if opts.Path != "" && s.Cheatpath != opts.Path {
			continue
		}
		if opts.Tag != "" {
			found := false
			for _, t := range s.Tags {
				if t == opts.Tag {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		out = append(out, s)
	}
	return out
}

// consolidate returns one sheet per title; the most "local" (later cheatpath) wins.
func consolidate(sheets []*Sheet) []*Sheet {
	// Preserve order of cheatpaths: cheatpaths later in the config take
	// precedence, and sheets from the same cheatpath are kept in the order
	// they were encountered (sorted by title).
	m := map[string]*Sheet{}
	for _, s := range sheets {
		m[s.Title] = s
	}
	out := make([]*Sheet, 0, len(m))
	for _, s := range m {
		out = append(out, s)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Title < out[j].Title })
	return out
}
