package main

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// openPager starts the configured pager process and returns a writer
// that pipes to it. It also returns a close function that waits for
// the pager to complete.
func openPager(cfg *Config) (io.Writer, func()) {
	if cfg.Pager == "" {
		return os.Stdout, func() {}
	}
	parts := strings.Fields(cfg.Pager)
	if len(parts) == 0 {
		return os.Stdout, func() {}
	}
	cmd := exec.Command(parts[0], parts[1:]...)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return os.Stdout, func() {}
	}
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		return os.Stdout, func() {}
	}
	return stdin, func() {
		stdin.(io.Closer).Close()
		cmd.Wait()
	}
}

func cmdDirectories(cfg *Config, opts *Options) {
	out, closer := openPager(cfg)
	defer closer()
	writeDirectories(out, cfg)
}

func writeDirectories(out io.Writer, cfg *Config) {
	// Compute max name length
	maxLen := 0
	for _, cp := range cfg.Cheatpaths {
		if len(cp.Name) > maxLen {
			maxLen = len(cp.Name)
		}
	}
	for _, cp := range cfg.Cheatpaths {
		fmt.Fprintf(out, "%s:%s %s\n", cp.Name, strings.Repeat(" ", maxLen-len(cp.Name)), cp.Path)
	}
}

