	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	tagSet := map[string]bool{}
	for _, s := range sheets {
		for _, t := range s.Tags {
			tagSet[t] = true
		}
	}
	var tags []string
	for t := range tagSet {
		tags = append(tags, t)
	}
	sort.Strings(tags)
	out, closer := openPager(cfg)
	defer closer()
	for _, t := range tags {
		fmt.Fprintln(out, t)
	}
}

func cmdList(cfg *Config, opts *Options) {
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	sheets = filteredSheets(sheets, opts)

	// Apply title filter if provided (substring)
	if len(opts.Args) > 0 {
		q := opts.Args[0]
		var filtered []*Sheet
		for _, s := range sheets {
			if strings.Contains(s.Title, q) {
				filtered = append(filtered, s)
			}
		}
		sheets = filtered
	}

	// Sort sheets
	sort.Slice(sheets, func(i, j int) bool {
		if sheets[i].Title != sheets[j].Title {
			return sheets[i].Title < sheets[j].Title
		}
		return sheets[i].Path < sheets[j].Path
	})

	if len(sheets) == 0 {
		os.Exit(2)
	}

	out, closer := openPager(cfg)
	defer closer()

	if opts.Brief {
		// Only title and tags
		titleW := len("title:")
		for _, s := range sheets {
			if len(s.Title) > titleW {
				titleW = len(s.Title)
			}
		}
		fmt.Fprintf(out, "%s%s tags:\n", "title:", strings.Repeat(" ", titleW-len("title:")))
		for _, s := range sheets {
			fmt.Fprintf(out, "%s%s %s\n", s.Title, strings.Repeat(" ", titleW-len(s.Title)), strings.Join(s.Tags, ","))
		}
		return
	}

	// list mode: title, file, tags
	titleW := len("title:")
	fileW := len("file:")
	for _, s := range sheets {
		if len(s.Title) > titleW {
			titleW = len(s.Title)
		}
		if len(s.Path) > fileW {
			fileW = len(s.Path)
		}
	}
	fmt.Fprintf(out, "%s%s %s%s tags:\n",
		"title:", strings.Repeat(" ", titleW-len("title:")),
		"file:", strings.Repeat(" ", fileW-len("file:")))
	for _, s := range sheets {
		fmt.Fprintf(out, "%s%s %s%s %s\n",
			s.Title, strings.Repeat(" ", titleW-len(s.Title)),
			s.Path, strings.Repeat(" ", fileW-len(s.Path)),
			strings.Join(s.Tags, ","))
	}
}

func cmdSearch(cfg *Config, opts *Options) {
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	sheets = filteredSheets(sheets, opts)

	// Filter by sheet name if specified
	if len(opts.Args) > 0 {
		q := opts.Args[0]
		var filtered []*Sheet
		for _, s := range sheets {
			if s.Title == q {
				filtered = append(filtered, s)
			}
		}
		sheets = filtered
	}

	// Sort by title, then by cheatpath order
	sort.Slice(sheets, func(i, j int) bool {
		if sheets[i].Title != sheets[j].Title {
			return sheets[i].Title < sheets[j].Title
		}
		return cheatpathOrder(cfg, sheets[i].Cheatpath) < cheatpathOrder(cfg, sheets[j].Cheatpath)
	})

	phrase := opts.Search

	var re *regexp.Regexp
	if opts.Regex {
		re, err = regexp.Compile(phrase)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to compile regexp: %s, %s\n", phrase, err.Error())
			os.Exit(1)
		}
	}

	var results []searchResult
	for _, s := range sheets {
		matches := searchSheet(s, phrase, re)
		if len(matches) > 0 {
			results = append(results, searchResult{Sheet: s, Sections: matches})
		}
	}

	if len(results) == 0 {
		return
	}

	useColor := shouldColorize(cfg, opts)
	out, closer := openPager(cfg)
	defer closer()
	writeSearchResults(out, results, useColor, cfg)
}

type searchResult struct {
	Sheet    *Sheet
	Sections []string
}

func searchSheet(s *Sheet, phrase string, re *regexp.Regexp) []string {
	// Split text into sections separated by blank lines
	lines := strings.Split(s.Text, "\n")
	var sections []string
	var cur []string
	for _, ln := range lines {
		if strings.TrimSpace(ln) == "" {
			if len(cur) > 0 {
				sec := strings.Join(cur, "\n")
				if matchSection(sec, phrase, re) {
					sections = append(sections, sec)
				}
				cur = nil
			}
			continue
		}
		cur = append(cur, ln)
	}
	if len(cur) > 0 {
		sec := strings.Join(cur, "\n")
		if matchSection(sec, phrase, re) {
			sections = append(sections, sec)
		}
	}
	return sections
}

func matchSection(sec, phrase string, re *regexp.Regexp) bool {
	if phrase == "" && re == nil {
		return false
	}
	if re != nil {
		return re.MatchString(sec)
	}
	return strings.Contains(sec, phrase)
}

func writeSearchResults(out io.Writer, results []searchResult, color bool, cfg *Config) {
	for i, r := range results {
		if color {
			fmt.Fprintf(out, "%s \033[2m(%s)\033[0m\n", r.Sheet.Title, r.Sheet.Cheatpath)
		} else {
			fmt.Fprintf(out, "%s (%s)\n", r.Sheet.Title, r.Sheet.Cheatpath)
		}
		for j, sec := range r.Sections {
			// Each line in the section is prefixed with a tab
			text := sec
			if color {
				text = colorizeText(text, r.Sheet.Syntax, cfg)
			}
			tabbed := "\t" + strings.ReplaceAll(text, "\n", "\n\t")
			fmt.Fprint(out, tabbed)
			if j < len(r.Sections)-1 {
				fmt.Fprintln(out)
				fmt.Fprintln(out)
			}
		}
		if i < len(results)-1 {
			fmt.Fprintln(out)
			fmt.Fprintln(out)
		}
	}
}

func cheatpathOrder(cfg *Config, name string) int {
	for i, cp := range cfg.Cheatpaths {
		if cp.Name == name {
			return i
		}
	}
	return -1
}

func cmdView(cfg *Config, opts *Options) {
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	sheets = filteredSheets(sheets, opts)

	title := opts.Args[0]
	var matches []*Sheet
	for _, s := range sheets {
		if s.Title == title {
			matches = append(matches, s)
		}
	}
	if len(matches) == 0 {
		fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
		os.Exit(2)
	}

	useColor := shouldColorize(cfg, opts)
	out, closer := openPager(cfg)
	defer closer()

	if opts.All || len(matches) > 1 && opts.All {
		// view all matches (with header) - but only with -a
	}

	if opts.All {
		// Print all matches with header like search
		for i, s := range matches {
			if useColor {
				fmt.Fprintf(out, "%s \033[2m(%s)\033[0m\n", s.Title, s.Cheatpath)
			} else {
				fmt.Fprintf(out, "%s (%s)\n", s.Title, s.Cheatpath)
			}
			text := s.Text
			if useColor {
				text = colorizeText(text, s.Syntax, cfg)
			}
			tabbed := "\t" + strings.ReplaceAll(text, "\n", "\n\t")
			tabbed = strings.TrimRight(tabbed, "\t")
			fmt.Fprint(out, tabbed)
			if i < len(matches)-1 {
				fmt.Fprintln(out)
				fmt.Fprintln(out)
			}
		}
		return
	}

	// Default: show the last match (most local cheatpath, by order)
	sort.Slice(matches, func(i, j int) bool {
		return cheatpathOrder(cfg, matches[i].Cheatpath) < cheatpathOrder(cfg, matches[j].Cheatpath)
	})
	s := matches[len(matches)-1]
	text := s.Text
	if useColor {
		text = colorizeText(text, s.Syntax, cfg)
	}
	fmt.Fprint(out, text)
}

func cmdEdit(cfg *Config, opts *Options) {
	title := opts.Edit
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	// Consider all sheets, including readonly ones
	sheets = filteredSheets(sheets, opts)

	var existing *Sheet
	// Find the most-local match
	for _, s := range sheets {
		if s.Title == title {
			existing = s
		}
	}

	// Choose writable path
	// When -p is given, use that path (must not be readonly to create new).
	var targetCp *Cheatpath
	if opts.Path != "" {
		for i := range cfg.Cheatpaths {
			if cfg.Cheatpaths[i].Name == opts.Path {
				targetCp = &cfg.Cheatpaths[i]
				break
			}
		}
	} else {
		// Use last writable path
