			}
		}
		sheets = filtered
	}

	// Sort by title, then by cheatpath order
	sort.Slice(sheets, func(i, j int) bool {
		if sheets[i].Title != sheets[j].Title {
			return sheets[i].Title < sheets[j].Title
		}
		return cheatpathOrder(cfg, sheets[i].Cheatpath) < cheatpathOrder(cfg, sheets[j].Cheatpath)
	})

	phrase := opts.Search

	var re *regexp.Regexp
	if opts.Regex {
		re, err = regexp.Compile(phrase)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to compile regexp: %s, %s\n", phrase, err.Error())
			os.Exit(1)
		}
	}

	var results []searchResult
	for _, s := range sheets {
		matches := searchSheet(s, phrase, re)
		if len(matches) > 0 {
			results = append(results, searchResult{Sheet: s, Sections: matches})
		}
	}

	if len(results) == 0 {
		return
	}

