func cmdSearch(cfg *Config, opts *Options) {
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	sheets = filteredSheets(sheets, opts)

	// Filter by sheet name if specified
	if len(opts.Args) > 0 {
		q := opts.Args[0]
		var filtered []*Sheet
		for _, s := range sheets {
			if s.Title == q {
				filtered = append(filtered, s)
			}
		}
		sheets = filtered
	}

	// Sort by title, then by cheatpath order
	sort.Slice(sheets, func(i, j int) bool {
		if sheets[i].Title != sheets[j].Title {
			return sheets[i].Title < sheets[j].Title
		}
		return cheatpathOrder(cfg, sheets[i].Cheatpath) < cheatpathOrder(cfg, sheets[j].Cheatpath)
	})

	phrase := opts.Search

	var re *regexp.Regexp
	if opts.Regex {
		re, err = regexp.Compile(phrase)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to compile regexp: %s, %s\n", phrase, err.Error())
			os.Exit(1)
		}
	}

	var results []searchResult
	for _, s := range sheets {
		matches := searchSheet(s, phrase, re)
		if len(matches) > 0 {
			results = append(results, searchResult{Sheet: s, Sections: matches})
		}
	}

	if len(results) == 0 {
		return
	}

	useColor := shouldColorize(cfg, opts)
	out, closer := openPager(cfg)
	defer closer()
	writeSearchResults(out, results, useColor, cfg)
}

type searchResult struct {
	Sheet    *Sheet
	Sections []string
}

func searchSheet(s *Sheet, phrase string, re *regexp.Regexp) []string {
	// Split text into sections separated by blank lines
	lines := strings.Split(s.Text, "\n")
	var sections []string
	var cur []string
	for _, ln := range lines {
		if strings.TrimSpace(ln) == "" {
			if len(cur) > 0 {
				sec := strings.Join(cur, "\n")
				if matchSection(sec, phrase, re) {
					sections = append(sections, sec)
				}
				cur = nil
			}
			continue
		}
		cur = append(cur, ln)
	}
	if len(cur) > 0 {
		sec := strings.Join(cur, "\n")
		if matchSection(sec, phrase, re) {
			sections = append(sections, sec)
		}
	}
	return sections
}

func matchSection(sec, phrase string, re *regexp.Regexp) bool {
	if phrase == "" && re == nil {
		return false
	}
	if re != nil {
		return re.MatchString(sec)
	}
	return strings.Contains(sec, phrase)
}

func writeSearchResults(out io.Writer, results []searchResult, color bool, cfg *Config) {
	for i, r := range results {
		if color {
			fmt.Fprintf(out, "%s \033[2m(%s)\033[0m\n", r.Sheet.Title, r.Sheet.Cheatpath)
		} else {
			fmt.Fprintf(out, "%s (%s)\n", r.Sheet.Title, r.Sheet.Cheatpath)
		}
		for j, sec := range r.Sections {
			// Each line in the section is prefixed with a tab
			text := sec
			if color {
				text = colorizeText(text, r.Sheet.Syntax, cfg)
			}
			tabbed := "\t" + strings.ReplaceAll(text, "\n", "\n\t")
			fmt.Fprint(out, tabbed)
			if j < len(r.Sections)-1 {
				fmt.Fprintln(out)
				fmt.Fprintln(out)
			}
		}
		if i < len(results)-1 {
			fmt.Fprintln(out)
			fmt.Fprintln(out)
		}
	}
}

func cheatpathOrder(cfg *Config, name string) int {
	for i, cp := range cfg.Cheatpaths {
		if cp.Name == name {
			return i
		}
	}
	return -1
}

func cmdView(cfg *Config, opts *Options) {
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
