	}
	sheets = filteredSheets(sheets, opts)

	title := opts.Args[0]
	var matches []*Sheet
	for _, s := range sheets {
		if s.Title == title {
			matches = append(matches, s)
		}
	}
	if len(matches) == 0 {
		fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
		os.Exit(2)
	}

	useColor := shouldColorize(cfg, opts)
	out, closer := openPager(cfg)
	defer closer()

	if opts.All || len(matches) > 1 && opts.All {
		// view all matches (with header) - but only with -a
	}

	if opts.All {
		// Print all matches with header like search
		for i, s := range matches {
			if useColor {
				fmt.Fprintf(out, "%s \033[2m(%s)\033[0m\n", s.Title, s.Cheatpath)
			} else {
				fmt.Fprintf(out, "%s (%s)\n", s.Title, s.Cheatpath)
			}
			text := s.Text
			if useColor {
				text = colorizeText(text, s.Syntax, cfg)
			}
			tabbed := "\t" + strings.ReplaceAll(text, "\n", "\n\t")
