func cmdEdit(cfg *Config, opts *Options) {
	title := opts.Edit
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	// Consider all sheets, including readonly ones
	sheets = filteredSheets(sheets, opts)

	var existing *Sheet
	// Find the most-local match
	for _, s := range sheets {
		if s.Title == title {
			existing = s
		}
	}

	// Choose writable path
	// When -p is given, use that path (must not be readonly to create new).
	var targetCp *Cheatpath
	if opts.Path != "" {
		for i := range cfg.Cheatpaths {
			if cfg.Cheatpaths[i].Name == opts.Path {
				targetCp = &cfg.Cheatpaths[i]
				break
			}
		}
	} else {
		// Use last writable path
		for i := range cfg.Cheatpaths {
			if !cfg.Cheatpaths[i].Readonly {
				targetCp = &cfg.Cheatpaths[i]
			}
		}
	}

	var path string
	if existing != nil {
		// Editing existing sheet - may need to copy from readonly
		if existing.Readonly {
			if targetCp == nil || targetCp.Readonly {
				fmt.Fprintf(os.Stderr, "failed to edit cheatsheet: no writable cheatpath available\n")
				os.Exit(1)
			}
			newPath := filepath.Join(targetCp.Path, title)
			if err := os.MkdirAll(filepath.Dir(newPath), 0755); err != nil {
				fmt.Fprintf(os.Stderr, "failed to create directory: %s\n", err.Error())
				os.Exit(1)
			}
			data, err := os.ReadFile(existing.Path)
			if err != nil {
				fmt.Fprintf(os.Stderr, "failed to read source: %s\n", err.Error())
				os.Exit(1)
			}
			if err := os.WriteFile(newPath, data, 0644); err != nil {
				fmt.Fprintf(os.Stderr, "failed to write copy: %s\n", err.Error())
				os.Exit(1)
			}
			path = newPath
		} else {
			path = existing.Path
		}
	} else {
		// New sheet
		if targetCp == nil || targetCp.Readonly {
			fmt.Fprintf(os.Stderr, "failed to edit cheatsheet: no writable cheatpath available\n")
			os.Exit(1)
		}
		path = filepath.Join(targetCp.Path, title)
		dir := filepath.Dir(path)
		if err := os.MkdirAll(dir, 0755); err != nil {
			fmt.Fprintf(os.Stderr, "failed to create directory: %s, %s\n", dir, err.Error())
			os.Exit(1)
		}
	}

	// Run editor
	editor := cfg.Editor
	editorParts := strings.Fields(editor)
	if len(editorParts) == 0 {
		fmt.Fprintln(os.Stderr, "failed to edit cheatsheet: no editor configured")
		os.Exit(1)
	}
	args := append(editorParts[1:], path)
	cmd := exec.Command(editorParts[0], args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "failed to run editor: %s\n", err.Error())
		os.Exit(1)
	}
}

