	if phrase == "" && re == nil {
		return false
	}
	if re != nil {
		return re.MatchString(sec)
	}
	return strings.Contains(sec, phrase)
}

func writeSearchResults(out io.Writer, results []searchResult, color bool, cfg *Config) {
	for i, r := range results {
		if color {
			fmt.Fprintf(out, "%s \033[2m(%s)\033[0m\n", r.Sheet.Title, r.Sheet.Cheatpath)
		} else {
			fmt.Fprintf(out, "%s (%s)\n", r.Sheet.Title, r.Sheet.Cheatpath)
		}
		for j, sec := range r.Sections {
			// Each line in the section is prefixed with a tab
			text := sec
			if color {
				text = colorizeText(text, r.Sheet.Syntax, cfg)
			}
			tabbed := "\t" + strings.ReplaceAll(text, "\n", "\n\t")
			fmt.Fprint(out, tabbed)
			if j < len(r.Sections)-1 {
				fmt.Fprintln(out)
				fmt.Fprintln(out)
			}
		}
		if i < len(results)-1 {
			fmt.Fprintln(out)
			fmt.Fprintln(out)
		}
	}
}

func cheatpathOrder(cfg *Config, name string) int {
	for i, cp := range cfg.Cheatpaths {
		if cp.Name == name {
			return i
		}
	}
	return -1
}

func cmdView(cfg *Config, opts *Options) {
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	sheets = filteredSheets(sheets, opts)

	title := opts.Args[0]
	var matches []*Sheet
	for _, s := range sheets {
		if s.Title == title {
			matches = append(matches, s)
		}
	}
	if len(matches) == 0 {
		fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
		os.Exit(2)
	}

	useColor := shouldColorize(cfg, opts)
	out, closer := openPager(cfg)
	defer closer()

	if opts.All || len(matches) > 1 && opts.All {
		// view all matches (with header) - but only with -a
	}

	if opts.All {
		// Print all matches with header like search
		for i, s := range matches {
			if useColor {
				fmt.Fprintf(out, "%s \033[2m(%s)\033[0m\n", s.Title, s.Cheatpath)
			} else {
				fmt.Fprintf(out, "%s (%s)\n", s.Title, s.Cheatpath)
			}
			text := s.Text
			if useColor {
				text = colorizeText(text, s.Syntax, cfg)
			}
			tabbed := "\t" + strings.ReplaceAll(text, "\n", "\n\t")
			tabbed = strings.TrimRight(tabbed, "\t")
			fmt.Fprint(out, tabbed)
			if i < len(matches)-1 {
				fmt.Fprintln(out)
				fmt.Fprintln(out)
			}
		}
		return
	}

	// Default: show the last match (most local cheatpath, by order)
	sort.Slice(matches, func(i, j int) bool {
		return cheatpathOrder(cfg, matches[i].Cheatpath) < cheatpathOrder(cfg, matches[j].Cheatpath)
	})
	s := matches[len(matches)-1]
	text := s.Text
	if useColor {
		text = colorizeText(text, s.Syntax, cfg)
	}
	fmt.Fprint(out, text)
}

func cmdEdit(cfg *Config, opts *Options) {
	title := opts.Edit
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}
	// Consider all sheets, including readonly ones
	sheets = filteredSheets(sheets, opts)

	var existing *Sheet
	// Find the most-local match
	for _, s := range sheets {
		if s.Title == title {
			existing = s
		}
	}

	// Choose writable path
	// When -p is given, use that path (must not be readonly to create new).
	var targetCp *Cheatpath
	if opts.Path != "" {
		for i := range cfg.Cheatpaths {
			if cfg.Cheatpaths[i].Name == opts.Path {
				targetCp = &cfg.Cheatpaths[i]
				break
			}
		}
	} else {
		// Use last writable path
		for i := range cfg.Cheatpaths {
			if !cfg.Cheatpaths[i].Readonly {
				targetCp = &cfg.Cheatpaths[i]
			}
		}
	}

	var path string
	if existing != nil {
		// Editing existing sheet - may need to copy from readonly
		if existing.Readonly {
			if targetCp == nil || targetCp.Readonly {
				fmt.Fprintf(os.Stderr, "failed to edit cheatsheet: no writable cheatpath available\n")
				os.Exit(1)
			}
			newPath := filepath.Join(targetCp.Path, title)
			if err := os.MkdirAll(filepath.Dir(newPath), 0755); err != nil {
				fmt.Fprintf(os.Stderr, "failed to create directory: %s\n", err.Error())
				os.Exit(1)
			}
			data, err := os.ReadFile(existing.Path)
			if err != nil {
				fmt.Fprintf(os.Stderr, "failed to read source: %s\n", err.Error())
				os.Exit(1)
			}
			if err := os.WriteFile(newPath, data, 0644); err != nil {
				fmt.Fprintf(os.Stderr, "failed to write copy: %s\n", err.Error())
				os.Exit(1)
			}
			path = newPath
		} else {
			path = existing.Path
		}
	} else {
		// New sheet
		if targetCp == nil || targetCp.Readonly {
			fmt.Fprintf(os.Stderr, "failed to edit cheatsheet: no writable cheatpath available\n")
			os.Exit(1)
		}
		path = filepath.Join(targetCp.Path, title)
		dir := filepath.Dir(path)
		if err := os.MkdirAll(dir, 0755); err != nil {
			fmt.Fprintf(os.Stderr, "failed to create directory: %s, %s\n", dir, err.Error())
			os.Exit(1)
		}
	}

	// Run editor
	editor := cfg.Editor
	editorParts := strings.Fields(editor)
	if len(editorParts) == 0 {
		fmt.Fprintln(os.Stderr, "failed to edit cheatsheet: no editor configured")
		os.Exit(1)
	}
	args := append(editorParts[1:], path)
	cmd := exec.Command(editorParts[0], args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "failed to run editor: %s\n", err.Error())
		os.Exit(1)
	}
}

func cmdRm(cfg *Config, opts *Options) {
	title := opts.Rm
	sheets, err := LoadSheets(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to list cheatsheets: %s\n", err.Error())
		os.Exit(1)
	}

	// Find the most-local writable match
	var toDelete *Sheet
	for _, s := range sheets {
		if s.Title == title {
			if !s.Readonly {
				toDelete = s
			} else if toDelete == nil {
				toDelete = s
			}
		}
	}
	if toDelete == nil {
		fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
		os.Exit(2)
	}
	if toDelete.Readonly {
		fmt.Fprintf(os.Stderr, "cheatsheet '%s' is read-only.\n", title)
		os.Exit(1)
	}
	if err := os.Remove(toDelete.Path); err != nil {
		fmt.Fprintf(os.Stderr, "failed to remove cheatsheet: %s\n", err.Error())
		os.Exit(1)
	}
}

func cmdUpdate(cfg *Config, opts *Options) {
	paths := cfg.Cheatpaths
	if opts.Path != "" {
		var filtered []Cheatpath
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.Path {
				filtered = append(filtered, cp)
			}
		}
		paths = filtered
	}
	anyErr := false
	maxName := 0
	for _, cp := range paths {
		if len(cp.Name) > maxName {
			maxName = len(cp.Name)
		}
	}
	for _, cp := range paths {
		status := updateCheatpath(cp)
		if status.IsError {
			anyErr = true
		}
		fmt.Printf("%s: %s\n", cp.Name, status.Message)
	}
	if anyErr {
		os.Exit(1)
	}
}

type updateStatus struct {
	Message string
	IsError bool
}

func updateCheatpath(cp Cheatpath) updateStatus {
	gitDir := filepath.Join(cp.Path, ".git")
	if info, err := os.Stat(gitDir); err != nil || !info.IsDir() {
		return updateStatus{Message: "skipped (not a git repository)"}
	}
	// Check dirty
	cmd := exec.Command("git", "-C", cp.Path, "status", "--porcelain")
	cmd.Stdin = nil
	out, err := cmd.Output()
	if err != nil {
		return updateStatus{Message: fmt.Sprintf("error (%s)", err.Error()), IsError: true}
	}
	if strings.TrimSpace(string(out)) != "" {
		return updateStatus{Message: "skipped (dirty worktree)"}
	}
	// Check for remote
	cmd = exec.Command("git", "-C", cp.Path, "remote")
	out, err = cmd.Output()
	if err != nil || strings.TrimSpace(string(out)) == "" {
		return updateStatus{Message: "error (remote not found)", IsError: true}
	}
	// Run git pull
	cmd = exec.Command("git", "-C", cp.Path, "pull", "--ff-only")
	if err := cmd.Run(); err != nil {
		return updateStatus{Message: fmt.Sprintf("error (%s)", err.Error()), IsError: true}
	}
	return updateStatus{Message: "updated"}
}

func shouldColorize(cfg *Config, opts *Options) bool {
	if opts.Colorize {
		return true
	}
	if cfg.Colorize && isTerminal(os.Stdout) {
		return true
	}
	return false
}

func isTerminal(f *os.File) bool {
	// Check via syscall ioctl TIOCGWINSZ or IsTerminal. Use a simple approach.
	info, err := f.Stat()
	if err != nil {
		return false
	}
	return (info.Mode() & os.ModeCharDevice) != 0
}
