	// Determine config base dir (where the cheatsheets go).
	configDir := determineConfigDir()
	editor := determineEditor()

	out := confTemplate
	out = strings.ReplaceAll(out, "CONFIG_DIR", configDir)
	out = strings.ReplaceAll(out, "EDITOR_PATH", editor)
	return out, nil
}

func determineConfigDir() string {
	if p := os.Getenv("CHEAT_CONFIG_PATH"); p != "" {
		return filepath.Dir(p)
	}
	if p := os.Getenv("XDG_CONFIG_HOME"); p != "" {
		return filepath.Join(p, "cheat")
	}
	if h := os.Getenv("HOME"); h != "" {
		return filepath.Join(h, ".config", "cheat")
	}
	return "cheat"
}

func determineEditor() string {
	if e := os.Getenv("VISUAL"); e != "" {
		return e
	}
	if e := os.Getenv("EDITOR"); e != "" {
		return e
	}
	// Search PATH for nano, then vim
	for _, candidate := range []string{"nano", "vim"} {
		if p := lookPath(candidate); p != "" {
			return p
		}
	}
	return "EDITOR_PATH"
}

