	pathEnv := os.Getenv("PATH")
	if pathEnv == "" {
		return ""
	}
	for _, dir := range strings.Split(pathEnv, ":") {
		if dir == "" {
			continue
		}
		p := filepath.Join(dir, name)
		if info, err := os.Stat(p); err == nil && !info.IsDir() {
			mode := info.Mode()
			if mode.Perm()&0111 != 0 {
				return p
			}
		}
	}
	return ""
}

