	case "zsh":
		return completionZsh, nil
	case "fish":
		return completionFish, nil
	case "powershell":
		return completionPowershell, nil
	default:
		return "", fmt.Errorf("unsupported shell: %s (valid: bash, zsh, fish, powershell)", shell)
	}
}
