package main

// colorizeText applies syntax highlighting (chroma-like) to the given text.
// For now, a simplified monokai-style highlighter is implemented.
// The output is an approximation - not byte-for-byte identical to chroma.
func colorizeText(text, syntax string, cfg *Config) string {
	// We don't implement full chroma here; just wrap all content in a default
	// foreground color.
	if cfg.Formatter == "terminal" {
		// 16-color
		return "\033[37m" + text + "\033[0m"
	}
	// terminal256
	return "\033[38;5;231m" + text + "\033[0m"
}
