package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

func runInstaller() error {
	reader := bufio.NewReader(os.Stdin)

	// Prompt: create config?
	yes, err := promptYN(reader, os.Stdout, "A config file was not found. Would you like to create one now? [Y/n]: ")
	if err != nil {
		return fmt.Errorf("failed to prompt: %s", err.Error())
	}
	if !yes {
		return nil
	}

	// Prompt: community sheets
	if _, err := promptYN(reader, os.Stdout, "Would you like to download the community cheatsheets? [Y/n]: "); err != nil {
		return fmt.Errorf("failed to run installer: failed to prompt: %s", err.Error())
	}

	// Determine the target conf path
	path := determineConfigWritePath()
	configDir := filepath.Dir(path)

	// Create cheatpaths directories
	for _, sub := range []string{"cheatsheets/personal", "cheatsheets/work"} {
		if err := os.MkdirAll(filepath.Join(configDir, sub), 0755); err != nil {
			return fmt.Errorf("failed to create directories: %s", err.Error())
		}
	}

	// Create config file
	data, err := renderInitConfig()
	if err != nil {
		return err
	}
	if err := os.MkdirAll(configDir, 0755); err != nil {
		return fmt.Errorf("failed to create directories: %s", err.Error())
	}
	if err := os.WriteFile(path, []byte(data), 0644); err != nil {
		return fmt.Errorf("failed to write config: %s", err.Error())
	}

	fmt.Fprintf(os.Stdout, "Created config file: %s\n", path)
	fmt.Fprintln(os.Stdout, "Please read this file for advanced configuration information.")
	return nil
}

func determineConfigWritePath() string {
	if p := os.Getenv("CHEAT_CONFIG_PATH"); p != "" {
		return p
	}
	if p := os.Getenv("XDG_CONFIG_HOME"); p != "" {
		return filepath.Join(p, "cheat", "conf.yml")
	}
	if h := os.Getenv("HOME"); h != "" {
		return filepath.Join(h, ".config", "cheat", "conf.yml")
	}
	return "cheat/conf.yml"
}

func promptYN(r *bufio.Reader, w io.Writer, msg string) (bool, error) {
	fmt.Fprint(w, msg)
	line, err := r.ReadString('\n')
	if err != nil && line == "" {
		return false, fmt.Errorf("EOF")
	}
	for len(line) > 0 && (line[len(line)-1] == '\n' || line[len(line)-1] == '\r') {
		line = line[:len(line)-1]
	}
	switch line {
	case "", "y", "Y", "yes", "Yes", "YES":
		return true, nil
	case "n", "N", "no", "No", "NO":
		return false, nil
	}
	return true, nil
}
EOF
