package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type Cheatpath struct {
	Name     string
	Path     string
	Tags     []string
	Readonly bool
}

type Config struct {
	Editor     string
	Colorize   bool
	Style      string
	Formatter  string
	Pager      string
	Cheatpaths []Cheatpath
	ConfPath   string
}

// resolveConfigPath returns the path to an existing config, or "" if not found.
func resolveConfigPath() (string, error) {
	if p := os.Getenv("CHEAT_CONFIG_PATH"); p != "" {
		if exp, err := expandPath(p); err == nil {
			if _, err := os.Stat(exp); err == nil {
				return exp, nil
			}
			return "", nil
		}
	}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		p := filepath.Join(xdg, "cheat", "conf.yml")
		if _, err := os.Stat(p); err == nil {
			return p, nil
		}
	}
	if home := os.Getenv("HOME"); home != "" {
		p := filepath.Join(home, ".config", "cheat", "conf.yml")
		if _, err := os.Stat(p); err == nil {
			return p, nil
		}
		p = filepath.Join(home, ".cheat", "conf.yml")
		if _, err := os.Stat(p); err == nil {
			return p, nil
		}
	}
	if _, err := os.Stat("/etc/cheat/conf.yml"); err == nil {
		return "/etc/cheat/conf.yml", nil
	}
	return "", nil
}

func expandPath(p string) (string, error) {
	if strings.HasPrefix(p, "~/") {
		if home := os.Getenv("HOME"); home != "" {
			return filepath.Join(home, p[2:]), nil
		}
	}
	return p, nil
}

func loadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("could not read config: %s", err.Error())
	}
	node, err := yamlParse(string(data))
	if err != nil {
		return nil, fmt.Errorf("could not unmarshal yaml: %s", err.Error())
	}

	cfg := &Config{
		ConfPath:  path,
		Style:     "monokai",
		Formatter: "terminal256",
		Pager:     "",
	}

	if s, ok := node.GetString("editor"); ok {
		cfg.Editor = s
	}
	if b, ok := node.GetBool("colorize"); ok {
		cfg.Colorize = b
	}
	if s, ok := node.GetString("style"); ok {
		cfg.Style = s
	}
	if s, ok := node.GetString("formatter"); ok {
		cfg.Formatter = s
	}
	if s, ok := node.GetString("pager"); ok {
		cfg.Pager = s
	}

	// Environment overrides
	if env := os.Getenv("VISUAL"); env != "" {
		cfg.Editor = env
	} else if env := os.Getenv("EDITOR"); env != "" {
		cfg.Editor = env
	}

	if cfg.Editor == "" {
		return nil, fmt.Errorf("no editor set")
	}

	// Parse cheatpaths
	cpNode := node.GetNode("cheatpaths")
	if cpNode == nil || cpNode.Kind == "null" {
		return nil, fmt.Errorf("config error: no cheatpaths specified")
	}
	if cpNode.Kind != "sequence" || len(cpNode.Seq) == 0 {
		return nil, fmt.Errorf("config error: no cheatpaths specified")
	}

	var paths []Cheatpath
	for _, item := range cpNode.Seq {
		if item.Kind != "mapping" {
			continue
		}
		cp := Cheatpath{}
		if s, ok := item.GetString("name"); ok {
			cp.Name = s
		}
		if s, ok := item.GetString("path"); ok {
			cp.Path = s
		}
		if b, ok := item.GetBool("readonly"); ok {
			cp.Readonly = b
		}
		tn := item.GetNode("tags")
		if tn != nil {
			cp.Tags = tn.AsStrings()
		}
		cp.Path, _ = expandPath(cp.Path)
		paths = append(paths, cp)
	}

	// Validate paths
	var validated []Cheatpath
	for _, p := range paths {
		// Attempt glob expansion for `**` patterns or other wildcards
		expanded, err := expandGlob(p.Path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' could not be resolved, skipping\n", p.Path)
			continue
		}
		if len(expanded) == 0 {
			// Path doesn't exist
			if _, statErr := os.Stat(p.Path); statErr != nil {
				if p.Path != "" {
					fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", p.Path)
					continue
				}
			}
		}
		if len(expanded) == 1 && expanded[0] == p.Path {
			validated = append(validated, p)
		} else if len(expanded) == 0 {
			validated = append(validated, p)
		} else {
			for _, e := range expanded {
				np := p
				np.Path = e
				validated = append(validated, np)
			}
		}
	}

	// Add CWD's .cheat if found
	if cp := findCwdCheatpath(); cp != nil {
		validated = append(validated, *cp)
	}

	cfg.Cheatpaths = validated
	return cfg, nil
}

func expandGlob(pattern string) ([]string, error) {
	if strings.Contains(pattern, "*") {
		matches, err := filepath.Glob(pattern)
		if err != nil {
			return nil, err
		}
		return matches, nil
	}
	if pattern == "" {
		return []string{""}, nil
	}
	if _, err := os.Stat(pattern); err != nil {
		return nil, nil
	}
	return []string{pattern}, nil
}

func findCwdCheatpath() *Cheatpath {
	cwd, err := os.Getwd()
	if err != nil {
		return nil
	}
	cur := cwd
	for {
		candidate := filepath.Join(cur, ".cheat")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return &Cheatpath{
				Name:     "cwd",
				Path:     candidate,
				Tags:     nil,
				Readonly: false,
			}
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return nil
}
EOF
