cat > /workspace/src/colorize.go <<'EOF'
package main

import (
	"regexp"
	"strings"
)

// colorizeText applies a basic syntax highlighting to the given text.
// This is an approximation of chroma's output (not byte-identical).
func colorizeText(text, syntax string, cfg *Config) string {
	// Default syntax if unset
	if syntax == "" {
		syntax = "bash"
	}
	switch cfg.Formatter {
	case "terminal":
		return colorizeTerminal(text, syntax, cfg)
	case "terminal16m":
		return colorizeTerminal256(text, syntax, cfg)
	default:
		return colorizeTerminal256(text, syntax, cfg)
	}
}

// colorizeTerminal256 produces an ANSI-colored representation of text using
// 256-color codes. It implements a very small subset of chroma's lexer+
// formatter behavior for monokai-like themes and common cheat cheatsheets.
func colorizeTerminal256(text, syntax string, cfg *Config) string {
	var out strings.Builder
	// For bash-like syntaxes, colorize comments gray and rest white.
	// Split into lines, process each.
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		coloredLine := colorizeLine(line, syntax)
		out.WriteString(coloredLine)
		if i < len(lines)-1 {
			out.WriteString("\n")
		}
	}
	return out.String()
}

var commentRe = regexp.MustCompile(`^([ \t]*)(#.*)$`)

func colorizeLine(line, syntax string) string {
	// Simple: if line is a bash comment, color it gray
	if m := commentRe.FindStringSubmatch(line); m != nil {
		return m[1] + "\033[38;5;242m" + m[2] + "\033[0m"
	}
	if line == "" {
		return ""
	}
	return "\033[38;5;231m" + line + "\033[0m"
}

func colorizeTerminal(text, syntax string, cfg *Config) string {
